package hu.synostream.android;
import android.app.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;
@RunWith(AndroidJUnit4.class)
public class Lifecycle051Test {
 Android050FlowTest flow=new Android050FlowTest();
 @After public void cleanup()throws Exception{if(flow.app!=null)flow.instrumentation.runOnMainSync(()->{flow.app.cancelScan();flow.app.epoch++;flow.app.torrentDraft.close();});flow.cleanup();}
 void add()throws Exception{MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->{try{MainActivity a=current;if(a.downloadsUi==null){a.downloadsUi=new DownloadsUi(a);a.downloadsUi.show();}java.lang.reflect.Method m=DownloadsUi.class.getDeclaredMethod("addition");m.setAccessible(true);m.invoke(a.downloadsUi);}catch(Exception e){throw new RuntimeException(e);}});assertTrue(flow.device.wait(Until.hasObject(By.text("Új torrent")),10000));}
 @Test public void torrentDraftSurvivesRotationAndNewDialogStartsEmpty()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());add();List<UiObject2> inputs=flow.device.findObjects(By.clazz("android.widget.EditText"));assertEquals(2,inputs.size());inputs.get(0).setText("https://example.org/rotation.torrent");inputs.get(1).setText("video/Filmek");flow.device.setOrientationLeft();assertTrue(flow.device.wait(Until.hasObject(By.text("Új torrent")),10000));assertTrue(flow.device.wait(Until.hasObject(By.text("https://example.org/rotation.torrent")),10000));assertNotNull(flow.device.findObject(By.text("video/Filmek")));flow.instrumentation.runOnMainSync(()->{flow.app.torrentDraft.bytes=new byte[]{1};flow.app.torrentDraft.filename="old.torrent";});flow.click("detail_close");add();assertNull(flow.app.torrentDraft.bytes);assertEquals("",flow.app.torrentDraft.filename);assertEquals("",java.util.Objects.toString(flow.device.findObjects(By.clazz("android.widget.EditText")).get(0).getText(),""));}}
 @Test public void editorPreservesNameAndTypeOnRotation()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->new LibraryUi(current).create());assertTrue(flow.device.wait(Until.hasObject(By.res(flow.pkg+":id/library_name")),10000));flow.device.findObject(By.res(flow.pkg+":id/library_name")).setText("Rajzfilmsorozatok");flow.device.findObject(By.text("TV műsorok")).click();flow.device.setOrientationLeft();assertTrue(flow.device.wait(Until.hasObject(By.text("Rajzfilmsorozatok")),10000));assertTrue(flow.device.findObject(By.text("TV műsorok")).isChecked());assertEquals("Rajzfilmsorozatok",flow.app.libraryDraft.optString("name"));assertFalse(flow.app.libraryDraft.optBoolean("movie"));}}
 @Test public void cancelledAudioSelectionStopsUnusedService()throws Exception{try(FakeNas nas=new FakeNas()){String path="/Movies/Multilingual.mkv";nas.files.put(path,Android050FlowTest.join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},Android050FlowTest.elem(0x1654ae6b,Android050FlowTest.join(Android050FlowTest.track(1,"hun"),Android050FlowTest.track(2,"eng")))));flow.setup(nas,List.of(new Library.Card(path,"Hangsávpróba",true)));flow.device.executeShellCommand("pm grant "+flow.pkg+" android.permission.POST_NOTIFICATIONS");MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->current.play(path,false));assertTrue(flow.device.wait(Until.hasObject(By.text("Szám 1: hun (ac3)")),15000));flow.device.pressBack();long deadline=System.currentTimeMillis()+10000;while(StreamService.readyUri!=null&&System.currentTimeMillis()<deadline)Thread.sleep(50);assertNull(StreamService.readyUri);assertFalse(flow.activity().playbackBusy);}}
 @Test public void audioSelectionRestoresAfterRotation()throws Exception{try(FakeNas nas=new FakeNas()){String path="/Movies/Multilingual.mkv";nas.files.put(path,Android050FlowTest.join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},Android050FlowTest.elem(0x1654ae6b,Android050FlowTest.join(Android050FlowTest.track(1,"hun"),Android050FlowTest.track(2,"eng")))));flow.setup(nas,List.of(new Library.Card(path,"Hangsávpróba",true)));flow.device.executeShellCommand("pm grant "+flow.pkg+" android.permission.POST_NOTIFICATIONS");MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->current.play(path,false));assertTrue(flow.device.wait(Until.hasObject(By.text("Szám 1: hun (ac3)")),15000));flow.device.setOrientationLeft();assertTrue(flow.device.wait(Until.hasObject(By.text("Szám 1: hun (ac3)")),15000));assertNotNull(flow.device.findObject(By.text("Szám 2: eng (ac3)")));}}
 @Test public void backClosesSearchAndReturnsFromSettings()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());flow.device.findObject(By.desc("Keresés")).click();assertTrue(flow.device.wait(Until.hasObject(By.res(flow.pkg+":id/search_box")),5000));MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->((android.view.inputmethod.InputMethodManager)flow.context.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(current.getWindow().getDecorView().getWindowToken(),0));flow.device.waitForIdle();flow.device.pressBack();assertTrue("Back must close search",flow.device.wait(Until.gone(By.res(flow.pkg+":id/search_box")),5000));flow.click("menu_button");flow.text("Beállítások");assertTrue("Settings must appear",flow.device.wait(Until.hasObject(By.text("Lejátszási kapcsolat leállítása")),5000));flow.instrumentation.runOnMainSync(()->((android.view.inputmethod.InputMethodManager)flow.context.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(current.getWindow().getDecorView().getWindowToken(),0));flow.device.waitForIdle();Thread.sleep(500);flow.device.pressBack();assertTrue("Back must return from settings (page="+flow.app.page+")",flow.device.wait(Until.hasObject(By.res(flow.pkg+":id/page_title").text("Filmek")),5000));assertEquals("movies",flow.app.page);}}

 @Test public void pairingJsonMimeIsReadDuringLibraryScan()throws Exception{try(FakeNas nas=new FakeNas()){nas.jsonMime=true;String id="00000000000000000000000000000001";nas.folders.add("/Movies/.synostream");nas.folders.add("/Movies/.synostream/parositasok");org.json.JSONObject event=new org.json.JSONObject().put("format_version",1).put("event_id",id).put("relative_path","Demo.Movie.2020.mkv").put("media_type","movie").put("tmdb_id",99).put("title","Kézi cím").put("deleted",false).put("generation",1).put("created_ns",1);nas.files.put("/Movies/.synostream/parositasok/"+id+".json",event.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));NasClient client=new NasClient(new NasClient.Credentials(nas.address(),"","fixture-user","fixture-password",""));client.connect();Library library=new Library(client,"");java.util.List<Library.Card> cards=library.scan("/Movies",true,n->{});assertEquals(1,library.pairings.events);assertTrue(cards.stream().anyMatch(c->c.id==99&&c.title.equals("Kézi cím")));}}
 @Test public void downloadsReusesAlreadyAuthenticatedOtpSession()throws Exception{try(FakeNas nas=new FakeNas()){NasClient client=new NasClient(new NasClient.Credentials(nas.address(),"","fixture-user","fixture-password","123456"));client.connect();nas.rejectNewLogins=true;org.json.JSONObject[] memory={new org.json.JSONObject()};DownloadStation.Persistence store=new DownloadStation.Persistence(){public String get(String k,String d){return memory[0].optString(k,d);}public void put(String k,String v){try{memory[0].put(k,v);}catch(Exception e){throw new RuntimeException(e);}}};DownloadStation ds=new DownloadStation(client,store,"fixture");assertEquals(1,ds.tasks().size());ds.close();assertEquals(2,client.list("/Movies").size());assertEquals(1,nas.authLogins);}}
 void cached(String endpoint,java.util.Map<String,String> parameters,org.json.JSONObject value){new MetadataCache(flow.context).put("recognition-v2:"+endpoint+"?"+NasClient.form(new java.util.TreeMap<>(parameters)),value);}
 @Test public void completedSaveDoesNotReopenClosedCard()throws Exception{try(FakeNas nas=new FakeNas()){Library.Card card=new Library.Card("/Movies/Demo.Movie.2020.mkv","Fixture movie",true);flow.setup(nas,List.of(card));flow.app.store.secret("tmdb_key","fixture-key");org.json.JSONObject info=new org.json.JSONObject().put("id",99).put("title","Magyar próba").put("overview","Leírás").put("release_date","2020-01-01");cached("movie/99",Map.of("language","hu-HU"),info);for(String language:List.of("hu-HU","en-US"))for(String title:MediaLogic.titleVariants(MediaLogic.clean(card.title,false).title))cached("search/movie",Map.of("language",language,"query",title),new org.json.JSONObject().put("results",new org.json.JSONArray().put(info)));MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->current.showDetail(card));flow.click("detail_info");flow.click("metadata_search");assertTrue(flow.device.wait(Until.hasObject(By.text(java.util.regex.Pattern.compile("Magyar próba.*"))),10000));nas.uploadDelayMillis=1500;flow.device.findObject(By.text(java.util.regex.Pattern.compile("Magyar próba.*"))).click();flow.click("detail_close");flow.click("detail_close");long deadline=System.currentTimeMillis()+15000;while((nas.uploads==0||flow.app.metadataBusy)&&System.currentTimeMillis()<deadline)Thread.sleep(50);assertEquals(1,nas.uploads);assertFalse(flow.app.metadataBusy);assertFalse(flow.device.hasObject(By.res(flow.pkg+":id/detail_info")));}}
 @Test public void seasonWithoutKeyCanRetryAfterKeyIsSet()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());MainActivity current=flow.activity();SeriesUi ui=new SeriesUi(current,new DetailUi(current));Library.Card card=new Library.Card("/Series/First.Show","Sorozat",false);card.id=99;NasClient.Entry entry=new NasClient.Entry("S01E01.mkv","/Series/First.Show/S01E01.mkv",false,1);entry.season=1;entry.episode=1;Class<?> type=Class.forName("hu.synostream.android.SeriesUi$SeasonAdapter");java.lang.reflect.Constructor<?> constructor=type.getDeclaredConstructor(SeriesUi.class,Library.Card.class,List.class);constructor.setAccessible(true);Object[] adapter={null};android.app.Dialog[] dialog={null};flow.instrumentation.runOnMainSync(()->{try{adapter[0]=constructor.newInstance(ui,card,List.of(entry));dialog[0]=current.screenDialog();current.showScreen(dialog[0],current.column());}catch(Exception e){throw new RuntimeException(e);}});java.lang.reflect.Method load=SeriesUi.class.getDeclaredMethod("loadSeason",type,int.class,android.app.Dialog.class);load.setAccessible(true);java.lang.reflect.Field requested=type.getDeclaredField("requested");requested.setAccessible(true);flow.instrumentation.runOnMainSync(()->{try{load.invoke(ui,adapter[0],1,dialog[0]);}catch(Exception e){throw new RuntimeException(e);}});flow.app.detail.submit(()->{}).get(5,java.util.concurrent.TimeUnit.SECONDS);long retryDeadline=System.currentTimeMillis()+5000;boolean[] cleared={false};do{flow.instrumentation.runOnMainSync(()->{try{cleared[0]=((Set<?>)requested.get(adapter[0])).isEmpty();}catch(Exception e){throw new RuntimeException(e);}});if(!cleared[0])Thread.sleep(25);}while(!cleared[0]&&System.currentTimeMillis()<retryDeadline);assertTrue("Failed request must become retryable",cleared[0]);flow.app.store.secret("tmdb_key","fixture-key");cached("tv/99/season/1",Map.of("language","hu-HU"),new org.json.JSONObject().put("episodes",new org.json.JSONArray().put(new org.json.JSONObject().put("episode_number",1).put("name","Újrapróbált epizód"))));flow.instrumentation.runOnMainSync(()->{try{load.invoke(ui,adapter[0],1,dialog[0]);}catch(Exception e){throw new RuntimeException(e);}});java.lang.reflect.Field metadata=type.getDeclaredField("metadata");metadata.setAccessible(true);long until=System.currentTimeMillis()+5000;while(((Map<?,?>)metadata.get(adapter[0])).isEmpty()&&System.currentTimeMillis()<until){flow.instrumentation.waitForIdleSync();Thread.sleep(25);}assertEquals("Újrapróbált epizód",((org.json.JSONObject)((Map<?,?>)metadata.get(adapter[0])).get("1:1")).getString("name"));}}
 @Test public void recycledTileUsesNewCardAndClickTarget()throws Exception{try(FakeNas nas=new FakeNas()){Library.Card a=new Library.Card("/Movies/a.mkv","A",true),b=new Library.Card("/Movies/b.mkv","B",true);flow.setup(nas,List.of(a,b));assertTrue("First tile remains accessible after measurement",flow.device.wait(Until.hasObject(By.desc("A")),10000));MainActivity current=flow.activity();flow.instrumentation.runOnMainSync(()->{GridView grid=current.findViewById(R.id.poster_grid);android.widget.BaseAdapter adapter=(android.widget.BaseAdapter)grid.getAdapter();android.view.View first=adapter.getView(0,null,grid),reused=adapter.getView(1,first,grid);assertSame(first,reused);assertEquals("B",reused.getContentDescription());reused.performClick();assertEquals("B",current.detailCard.title);});}}
 @Test public void newLoginAddressKeepsExistingLibrarySources()throws Exception{try(FakeNas first=new FakeNas();FakeNas second=new FakeNas()){flow.setup(first,List.of());String expected=flow.app.libraries.toString();flow.app.store.put("libraries_owner",flow.app.identity);flow.click("menu_button");flow.text("Kijelentkezés");assertTrue(flow.device.wait(Until.hasObject(By.res(flow.pkg+":id/login_address")),10000));flow.device.findObject(By.res(flow.pkg+":id/login_address")).setText(second.address().replace("http://","HTTP://"));flow.device.findObject(By.res(flow.pkg+":id/login_user")).setText("fixture-user");flow.device.findObject(By.res(flow.pkg+":id/login_password")).setText("fixture-password");flow.click("login_button");assertTrue(flow.device.wait(Until.hasObject(By.res(flow.pkg+":id/poster_grid")),10000));assertEquals(expected,flow.app.libraries.toString());assertEquals(List.of("/Movies"),LibraryConfig.paths(flow.app.selected()));}}
 @Test public void rotatingDuringPreparationShowsOnlyFileSelection()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());nas.previewDelayMillis=1500;add();flow.device.findObjects(By.clazz("android.widget.EditText")).get(0).setText("https://example.org/rotation.torrent");flow.text("Hozzáadás");flow.device.setOrientationLeft();assertTrue(flow.device.wait(Until.hasObject(By.text("release.nfo")),20000));assertFalse(flow.device.hasObject(By.text("Új torrent")));assertFalse(flow.app.torrentDraft.open);assertEquals(0,nas.starts);}}
}
